package app;
import java.time.*;
import java.time.temporal.*;
class Module4 {
 static double total(Booking b){double sum=0;for(int id:b.roomIds){Room r=Data.room(id);if(r==null)continue;for(LocalDate d=b.in;d.isBefore(b.out);d=d.plusDays(1)){double night=r.price;if(d.getDayOfWeek()==DayOfWeek.FRIDAY||d.getDayOfWeek()==DayOfWeek.SATURDAY)night*=1.20;sum+=night*(r.price<7500?1.12:1.18);}}return Math.round(sum*100.0)/100.0;}
 static void menu(){while(true){Data.expire();System.out.println("\n--- MODULE 4: PAYMENT & CANCELLATION ---\n1 Show price\n2 Pay\n3 Cancel booking\n4 Hotel cancel\n5 Payment records\n0 Back");int c=Data.number("Choice: ");if(c==0)return;if(c==1)price();else if(c==2)pay();else if(c==3)cancel(false);else if(c==4)cancel(true);else if(c==5)records();}}
 static void price(){Booking b=Data.booking(Data.number("Booking ID: "));if(b!=null)System.out.println("Total with weekend surcharge and GST: Rs "+total(b));}
 static void pay(){Booking b=Data.booking(Data.number("Booking ID: "));if(b==null||!b.status.equals("Pending Payment")){System.out.println("No active pending booking.");return;}System.out.println("1 UPI\n2 Card\n3 Pay at Hotel");int c=Data.number("Method: ");String method=c==1?"UPI":c==2?"Card":c==3?"Pay at Hotel":"";if(method.isEmpty())return;long nights=ChronoUnit.DAYS.between(b.in,b.out);if(c==3&&nights>2){System.out.println("Pay at Hotel only for up to 2 nights.");return;}if(c==3){b.status="Confirmed";Data.payments.add(new Payment(b.id,b.total,method,"Pending"));System.out.println("Confirmed: payment due at hotel.");return;}String result=Data.ask("Simulate online payment success? (yes/no): ");if(result.equalsIgnoreCase("yes")){b.status="Confirmed";Data.payments.add(new Payment(b.id,b.total,method,"Paid"));System.out.println("Payment successful. Confirmed.");}else{b.status="Cancelled";Data.payments.add(new Payment(b.id,b.total,method,"Failed"));System.out.println("Payment failed; room released.");}}
 static void cancel(boolean hotel){Booking b=Data.booking(Data.number("Booking ID: "));if(b==null||b.status.equals("Cancelled")||b.status.equals("Checked Out")||b.status.equals("No Show")){System.out.println("Cannot cancel.");return;}double pct=0;if(hotel)pct=1;else{long hrs=Duration.between(LocalDateTime.now(),b.in.atTime(14,0)).toHours();if(hrs>48)pct=1;else if(hrs>=24)pct=.5;}double refund=0;for(Payment p:Data.payments)if(p.bookingId==b.id&&p.status.equals("Paid")){refund+=p.amount*pct;p.status="Refunded";}b.status="Cancelled";System.out.println("Booking cancelled. Refund due Rs "+String.format("%.2f",refund)+" (simulated).");}
 static void records(){for(Payment p:Data.payments)System.out.println("Booking "+p.bookingId+" | Rs "+p.amount+" | "+p.date+" | "+p.method+" | "+p.status);}
}
